class LRU:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.order = []  # list to track usage order, most recent at end

    def get(self, k):
        if k in self.cache:
            # Move to end (most recently used)
            self.order.remove(k)
            self.order.append(k)
            return self.cache[k]
        return -1

    def put(self, k, v):
        if k in self.cache:
            # Update value and move to end
            self.cache[k] = v
            self.order.remove(k)
            self.order.append(k)
        else:
            if len(self.cache) >= self.capacity:
                # Evict least recently used (first in order)
                lru_key = self.order.pop(0)
                del self.cache[lru_key]
            self.cache[k] = v
            self.order.append(k)
